beforeExample:
import java.io.UnsupportedEncodingException;
import java.net.URLDecoder;

public class Example {
    public String decodeUrl(String path) throws UnsupportedEncodingException {
        // This is the pattern to match
        return URLDecoder.decode(path, "UTF-8");
    }

    public String anotherDecode(String input) {
        try {
            return URLDecoder.decode(input, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }
}

afterExample:
import java.io.UnsupportedEncodingException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

public class Example {
    // The 'throws UnsupportedEncodingException' should be removed as the new API doesn't throw it
    public String decodeUrl(String path) {
        // Expected replacement
        return URLDecoder.decode(path, StandardCharsets.UTF_8);
    }

    public String anotherDecode(String input) {
        // The try-catch block becomes redundant
        return URLDecoder.decode(input, StandardCharsets.UTF_8);
    }
}

