import java.io.UnsupportedEncodingException;
import java.net.URLDecoder;

public class NegativeExample {
    public String decodeUrlIso(String path) throws UnsupportedEncodingException {
        // Should not match other charsets
        return URLDecoder.decode(path, "ISO-8859-1");
    }

    public String encodeUrl(String path) throws UnsupportedEncodingException {
        // Should not match URLEncoder
        return java.net.URLEncoder.encode(path, "UTF-8");
    }

    public byte[] getBytes(String text) throws UnsupportedEncodingException {
        // Should not match String.getBytes()
        return text.getBytes("UTF-8");
    }
}
